    public virtual async Task DeleteAllAsync(string? filterText = null, string? title = null, string? slug = null, string? summary = null, string? description = null, string? requirements = null, string? benefits = null, string? thumbnailUrl = null, string? coverImageUrl = null, EmploymentType? employmentType = null, WorkMode? workMode = null, ExperienceLevel? experienceLevel = null, decimal? salaryMinMin = null, decimal? salaryMinMax = null, decimal? salaryMaxMin = null, decimal? salaryMaxMax = null, string? salaryText = null, string? salaryCurrency = null, string? location = null, string? contactEmail = null, string? contactPhone = null, string? applicationUrl = null, DateTime? publishedAtMin = null, DateTime? publishedAtMax = null, JobStatus? status = null, int? viewCountMin = null, int? viewCountMax = null, int? applicationCountMin = null, int? applicationCountMax = null, int? favoriteCountMin = null, int? favoriteCountMax = null, int? shareCountMin = null, int? shareCountMax = null, bool? isFeatured = null, bool? isUrgent = null, bool? isHot = null, string? seoTitle = null, string? seoDescription = null, string? seoKeywords = null, Guid? provinceId = null, Guid? wardId = null, Guid? jobCategoryId = null, CancellationToken cancellationToken = default)
