    }

    public virtual async Task<JobWithNavigationProperties> GetWithNavigationPropertiesAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var dbContext = await GetDbContextAsync();
        return (await GetDbSetAsync()).Where(b => b.Id == id).Select(job => new JobWithNavigationProperties { Job = job, Province = dbContext.Set<Province>().FirstOrDefault(c => c.Id == job.ProvinceId), Ward = dbContext.Set<Ward>().FirstOrDefault(c => c.Id == job.WardId), JobCategory = dbContext.Set<JobCategory>().FirstOrDefault(c => c.Id == job.JobCategoryId) }).FirstOrDefault();
    }

