    protected virtual async Task<IQueryable<JobWithNavigationProperties>> GetQueryForNavigationPropertiesAsync()
    {
        return from job in (await GetDbSetAsync())
               join province in (await GetDbContextAsync()).Set<Province>() on job.ProvinceId equals province.Id into provinces
               from province in provinces.DefaultIfEmpty()
               join ward in (await GetDbContextAsync()).Set<Ward>() on job.WardId equals ward.Id into wards
               from ward in wards.DefaultIfEmpty()
               join jobCategory in (await GetDbContextAsync()).Set<JobCategory>() on job.JobCategoryId equals jobCategory.Id into jobCategories
               from jobCategory in jobCategories.DefaultIfEmpty()
               select new JobWithNavigationProperties
               {
                   Job = job,
                   Province = province,
                   Ward = ward,
                   JobCategory = jobCategory
               };
    }

